interface ValidationResult {
  email: string;
  valid: boolean;
  normalized: string;
  errors: string[];
  warnings: string[];
  parts: { local: string; domain: string } | null;
}

const disposableDomains = new Set([
  'tempmail.com', 'throwaway.email', 'guerrillamail.com', 'mailinator.com',
  'yopmail.com', 'sharklasers.com', 'trashmail.com', '10minutemail.com'
]);

function validateEmail(email: string): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const trimmed = email.trim();

  if (!trimmed) {
    return { email: trimmed, valid: false, normalized: '', errors: ['email is empty'], warnings: [], parts: null };
  }

  if (trimmed.length > 254) errors.push('exceeds max length of 254 characters');

  const atIndex = trimmed.lastIndexOf('@');
  if (atIndex < 1) { errors.push('missing or misplaced @ symbol'); }

  const local = trimmed.substring(0, atIndex);
  const domain = trimmed.substring(atIndex + 1).toLowerCase();

  if (local.length > 64) errors.push('local part exceeds 64 characters');
  if (local.startsWith('.') || local.endsWith('.')) errors.push('local part cannot start or end with a dot');
  if (local.includes('..')) errors.push('local part cannot have consecutive dots');
  if (!/^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(local)) errors.push('local part contains invalid characters');

  if (!domain) errors.push('domain is empty');
  else if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,}$/.test(domain)) {
    errors.push('invalid domain format');
  }

  if (disposableDomains.has(domain)) warnings.push('disposable email domain detected');
  if (local.includes('+')) warnings.push('contains plus addressing (subaddressing)');
  if (domain === 'gmail.com' && local.includes('.')) warnings.push('gmail ignores dots in local part');

  // Normalize: lowercase, trim, remove gmail dots
  let normalized = `${local}@${domain}`;
  if (domain === 'gmail.com' || domain === 'googlemail.com') {
    const cleanLocal = local.split('+')[0].replace(/\./g, '');
    normalized = `${cleanLocal}@gmail.com`;
  }

  return {
    email: trimmed,
    valid: errors.length === 0,
    normalized,
    errors,
    warnings,
    parts: errors.length === 0 ? { local, domain } : null
  };
}

function main(req: { body: string }): { results: ValidationResult[] } | ValidationResult {
  const body = jsonParse(req.body, {} as any);

  // Batch mode
  if (Array.isArray(body.emails)) {
    return { results: body.emails.map((e: string) => validateEmail(e)) };
  }

  // Single mode
  return validateEmail(body.email || '');
}
